import numpy as np

def gap_zero(g):
    # at t = 0 the integral is asinh(1/D), so 1 = g asinh(1/D)
    return 1 / np.sinh(1 / g)

def critical_temperature(g):
    xi = np.linspace(0, 1, 200001)
    dxi = xi[1] - xi[0]
    def integral(t):
        with np.errstate(divide="ignore", invalid="ignore"):
            f = np.where(xi > 0, np.tanh(xi / (2 * t)) / xi, 1 / (2 * t))
        return g * (f.sum() - 0.5 * (f[0] + f[-1])) * dxi
    lo, hi = 1e-5, 1.0
    for _ in range(80):
        mid = 0.5 * (lo + hi)
        if integral(mid) > 1:
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)

exercises.solution:
At zero temperature the integral is elementary:

$$1 = g\int_0^1\frac{d\xi}{\sqrt{\xi^2 + \Delta^2}} = g\operatorname{asinh}\frac{1}{\Delta} \quad\Longrightarrow\quad \Delta(0) = \frac{1}{\sinh(1/g)} \approx 2e^{-1/g}.$$

At $T_c$ the gap vanishes and the integrand is $\tanh(\xi/2t)/\xi$, which has no closed-form integral, so bisect numerically:

```python
import numpy as np

def gap_zero(g):
    return 1 / np.sinh(1 / g)

def critical_temperature(g):
    xi = np.linspace(0, 1, 200001)
    dxi = xi[1] - xi[0]
    def integral(t):
        with np.errstate(divide="ignore", invalid="ignore"):
            f = np.where(xi > 0, np.tanh(xi / (2 * t)) / xi, 1 / (2 * t))
        return g * (f.sum() - 0.5 * (f[0] + f[-1])) * dxi
    lo, hi = 1e-5, 1.0
    for _ in range(80):
        mid = 0.5 * (lo + hi)
        if integral(mid) > 1:
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)
```

Asymptotically $k_BT_c = (2e^\gamma/\pi)\,e^{-1/g} \approx 1.134\,e^{-1/g}$ (with $\gamma$ Euler's constant), so $2\Delta(0)/k_BT_c \to 2\pi/e^\gamma = 3.528$: a number independent of the material, the metal's Debye energy and the coupling, which is why its measurement in the 1950s and 60s was such a convincing test of BCS theory.
